// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }

    function testFuzz_property(address sender, uint256 amount) public {
        vm.assume(sender != address(0));

        uint256 amt = bound(amount, 0, 100 ether);

        vm.deal(sender, amt);

        vm.warp(block.timestamp + 1);

        bool ok;
        vm.prank(sender);
        (bool success, ) = address(c).call{value: amt}("");
        ok = success;

        if (amt == 10 ether) {
            assertTrue(ok);
        } else {
            uint256 pb = c.pastBlockTime();
            if (ok) {
                assertTrue(pb == block.timestamp);
            } else {
                assertTrue(pb != block.timestamp);
            }
        }
    }
}
